{"stdout":"[package]
name = "toad-desktop"
description = "Toad's desktop shell on Tauri 2: one window onto the core, which runs in this process."
version.workspace = true
edition.workspace = true

[lib]
name = "toad_desktop_lib"
crate-type = ["staticlib", "cdylib", "rlib"]

[[test]]
name = "shell_path"
harness = false

[build-dependencies]
tauri-build = { version = "2", features = [] }

[dependencies]
tauri = { version = "2", features = ["tray-icon", "image-png"] }
tauri-plugin-clipboard-manager = "=2.3.3"
tauri-plugin-dialog = "=2.7.3"
tauri-plugin-opener = "=2.5.5"
tauri-plugin-window-state = "=2.4.1"
tauri-plugin-updater = "=2.11.0"
serde.workspace = true
semver = "1"
tempfile = "3"
tokio-util = "0.7"
serde_json.workspace = true
tokio = { workspace = true, features = ["rt-multi-thread"] }
rand = "0.9"
toad-core = { path = "../toad-core" }

# Toasts. On Linux and Windows the plugin posts them. On macOS the modern
# notification center does: it is the one that routes a click back and
# threads toasts per teammate, and the plugin's macOS path is the API Apple
# retired.
[target.'cfg(not(target_os = "macos"))'.dependencies]
tauri-plugin-notification = "=2.4.0"

[target.'cfg(target_os = "macos")'.dependencies]
objc2 = "0.6"
block2 = "0.6"
objc2-foundation = { version = "0.3", features = ["NSBundle", "NSString", "NSDictionary", "NSError", "NSValue", "NSObject"] }
objc2-user-notifications = { version = "0.3", features = [
    "UNUserNotificationCenter",
    "UNNotificationRequest",
    "UNNotificationContent",
    "UNNotificationResponse",
    "UNNotification",
    "UNNotificationSettings",
    "block2",
] }

[dev-dependencies]
tauri = { version = "2", features = ["test"] }
//! Tauri's default Windows manifest reaches the app binary as a compiled
//! resource for bins only. The library's test binary links Tauri without it,
//! so it loads the Common Controls that predate `TaskDialogIndirect` and dies
//! with STATUS_ENTRYPOINT_NOT_FOUND before a single test runs. So the same
//! manifest is linked into every binary this crate produces instead.
fn main() {
    let msvc = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows")
        && std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    let attributes = if msvc {
        let manifest = std::path::PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap())
            .join("windows-app-manifest.xml");
        println!("cargo:rerun-if-changed={}", manifest.display());
        println!("cargo:rustc-link-arg=/MANIFEST:EMBED");
        println!("cargo:rustc-link-arg=/MANIFESTINPUT:{}", manifest.display());
        tauri_build::Attributes::new()
            .windows_attributes(tauri_build::WindowsAttributes::new_without_app_manifest())
    } else {
        tauri_build::Attributes::new()
    };
    tauri_build::try_build(attributes).expect("failed to run tauri-build");
}
